import json,datetime
from pathlib import Path
p=Path(__file__).parent
ids=json.loads((p/'identities.json').read_text())['records']
deps=json.loads((p/'dependency-identities.json').read_text())['records']
out=json.loads((p/'forward-mapping.json').read_text())
units=[]
def add(n,name,basename,lines,selector,facts,peers=None):
 matches=[x for x in ids+deps if x['path'].endswith('/'+basename)]
 if not matches:raise ValueError(basename)
 src=dict(matches[0]);src.update(reader='/root/ui_full',status='FULL_READ',ranges=[[1,lines]],semantic_selector=selector)
 u={'id':f'UI65-U{n:03}','name':name,'sources':[src],'facts':[{'id':f'UI65-F{n:03}-{i:02}','assertion':f} for i,f in enumerate(facts,1)],'reader':'/root/ui_full','premise':'固定B8/R无插件并发，具名普通依赖正常；源请求不证明宿主/资源/执行，后段失败保留前缀且不补造ensure。','disposition':'OWN_FULL_PRIMARY_SOURCE_READ' if src['path'].startswith('Data/Scripts/016_UI/') else 'OWN_FULL_DEPENDENCY_READ','execution':'NOT_EXECUTED'}
 if peers:u['bounded_peer_receptions']=peers
 units.append(u)
